import './Home.css';

const Home = () => {
  return (
    <div className="home">
      <h1>Welcome to Our Camera Self-Studio</h1>
      <p>Capture your moments in a beautiful and minimalist setting.</p>
      <p>Explore our services and book your session today!</p>
    </div>
  );
};

export default Home;
